// Shared form controls and predictable modal lifecycle.
(function(){
  let serial=0,returnFocus=null;
  const textOf=x=>String(x??'');
  window.MMWidgets={combo(name,label,options,value='',placeholder='Select an option'){
    const key='mm-combo-'+(++serial),selected=options.find(o=>textOf(o.value)===textOf(value));
    let lastGroup='';
    const choices=options.map(o=>{let heading='';if(o.group&&o.group!==lastGroup){lastGroup=o.group;heading=`<div class="mm-combo-group">${esc(o.group)}</div>`}return heading+`<button type="button" role="option" class="mm-combo-option" data-mm-pick="${esc(o.value)}" data-mm-label="${esc(o.label)}" ${o.disabled?'disabled':''}>${esc(o.label)}</button>`}).join('');
    return `<label class="mm-combo-label">${esc(label)}<span class="mm-combo" data-mm-combo><input type="hidden" name="${esc(name)}" value="${esc(value)}"><span class="mm-combo-input"><input id="${key}" type="search" data-mm-search autocomplete="off" role="combobox" aria-expanded="false" aria-controls="${key}-list" placeholder="${esc(placeholder)}" value="${esc(selected?.label||'')}"><button type="button" data-mm-toggle aria-label="Open ${esc(label.replace(/\*/g,''))}">⌄</button></span><span class="mm-combo-list" id="${key}-list" role="listbox" hidden>${choices}<span class="mm-combo-empty" hidden>No results found.</span></span></span></label>`;
  }};
  function closeCombos(except){document.querySelectorAll('[data-mm-combo]').forEach(w=>{if(w===except)return;w.querySelector('.mm-combo-list').hidden=true;w.querySelector('[data-mm-search]').setAttribute('aria-expanded','false')})}
  function openCombo(w){closeCombos(w);let list=w.querySelector('.mm-combo-list'),input=w.querySelector('[data-mm-search]');list.hidden=false;input.setAttribute('aria-expanded','true');let rect=w.getBoundingClientRect(),below=window.innerHeight-rect.bottom-12,above=rect.top-12,height=Math.min(290,Math.max(below,above));Object.assign(list.style,{position:'fixed',left:rect.left+'px',width:rect.width+'px',maxHeight:height+'px',top:below<180&&above>below?'auto':(rect.bottom+4)+'px',bottom:below<180&&above>below?(window.innerHeight-rect.top+4)+'px':'auto'});input.select();w.querySelectorAll('.mm-combo-option,.mm-combo-group').forEach(x=>x.hidden=false)}
  document.addEventListener('click',e=>{let w=e.target.closest('[data-mm-combo]');if(!w){closeCombos();return}let item=e.target.closest('[data-mm-pick]');if(item){e.preventDefault();let value=w.querySelector('input[type=hidden]'),search=w.querySelector('[data-mm-search]');value.value=item.dataset.mmPick;search.value=item.dataset.mmLabel;w.querySelector('.mm-combo-list').hidden=true;search.setAttribute('aria-expanded','false');value.dispatchEvent(new Event('change',{bubbles:true}));value.dispatchEvent(new Event('input',{bubbles:true}));return}if(e.target.matches('[data-mm-search]')||e.target.closest('[data-mm-toggle]')){e.preventDefault();openCombo(w)}},true);
  document.addEventListener('input',e=>{if(!e.target.matches('[data-mm-search]'))return;let w=e.target.closest('[data-mm-combo]'),q=e.target.value.toLowerCase().trim(),found=0;w.querySelector('.mm-combo-list').hidden=false;w.querySelectorAll('.mm-combo-option').forEach(x=>{x.hidden=!x.textContent.toLowerCase().includes(q);if(!x.hidden)found++});w.querySelectorAll('.mm-combo-group').forEach(x=>x.hidden=!!q);w.querySelector('.mm-combo-empty').hidden=found>0});
  document.addEventListener('keydown',e=>{if(e.target.matches('.mm-combo-option')){let w=e.target.closest('[data-mm-combo]'),items=[...w.querySelectorAll('.mm-combo-option:not([hidden]):not([disabled])')],i=items.indexOf(e.target);if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();items[(i+(e.key==='ArrowDown'?1:-1)+items.length)%items.length]?.focus()}if(e.key==='Escape'){e.preventDefault();e.stopPropagation();closeCombos();w.querySelector('[data-mm-search]').focus()}return}if(!e.target.matches('[data-mm-search]'))return;let w=e.target.closest('[data-mm-combo]');if(e.key==='ArrowDown'){e.preventDefault();openCombo(w);w.querySelector('.mm-combo-option:not([hidden]):not([disabled])')?.focus()}if(e.key==='Escape'){closeCombos();e.stopPropagation()}});
  closeModal=function(){document.querySelectorAll('.modal-bg').forEach(e=>e.remove());modalOpen=false;if(returnFocus?.isConnected)returnFocus.focus()};
  showModal=function(title,body,submit,onSubmit){closeModal();returnFocus=document.activeElement;modalOpen=true;let modalId='mm-dialog-'+(++serial);document.body.insertAdjacentHTML('beforeend',`<div class="modal-bg"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="${modalId}"><header class="modal-head"><h2 id="${modalId}">${title}</h2><button type="button" class="icon-btn" id="modal-close" aria-label="Close">×</button></header><div class="modal-body">${body}</div><footer class="modal-foot"><button type="button" class="btn" id="modal-cancel">Cancel</button><button type="button" class="btn primary" id="modal-submit">${esc(submit||'Save')}</button></footer></section></div>`);let bg=document.querySelector('.modal-bg'),button=document.querySelector('#modal-submit');document.querySelector('#modal-close').onclick=document.querySelector('#modal-cancel').onclick=closeModal;bg.addEventListener('click',e=>{if(e.target===bg)closeModal()});button.onclick=()=>{let result;try{result=onSubmit?.()}catch(err){console.error(err);window.alert('Unable to save. '+err.message);return}if(result&&typeof result.then==='function'){button.disabled=true;result.then(value=>{if(value!==false)closeModal()}).catch(err=>window.alert('Unable to save. '+err.message)).finally(()=>{if(button.isConnected)button.disabled=false})}else if(result!==false)closeModal()};bg.querySelector('#modal-form')?.addEventListener('submit',e=>{e.preventDefault();button.click()});};
  formModal=function(title,fields,onSubmit,submit='Save Changes'){showModal(title,`<form id="modal-form" class="form two">${fields}</form>`,submit,()=>{let form=document.querySelector('#modal-form');if(!form.reportValidity())return false;return onSubmit(Object.fromEntries(new FormData(form)))})};
  document.addEventListener('keydown',e=>{let bg=document.querySelector('.modal-bg');if(!bg)return;if(e.key==='Escape'){e.preventDefault();closeModal()}if(e.key==='Tab'){let focus=[...bg.querySelectorAll('input:not([type=hidden]),select,textarea,button,a[href]')].filter(x=>!x.disabled&&!x.hidden&&x.closest('[hidden]')===null);if(!focus.length)return;if(e.shiftKey&&document.activeElement===focus[0]){e.preventDefault();focus.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===focus.at(-1)){e.preventDefault();focus[0].focus()}}});
})();
